	    public void EncodeBase64NVARCHARFields(ARInvoicePM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.ConfirmationNumber)) //T4 find type == nText 
            {
                entityPM.ConfirmationNumber = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.ConfirmationNumber));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.Description)) //T4 find type == nText 
            {
                entityPM.Description = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.Description));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SATXML)) //T4 find type == nText 
            {
                entityPM.SATXML = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SATXML));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SearchFields)) //T4 find type == nText 
            {
                entityPM.SearchFields = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SearchFields));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.InternalNotes)) //T4 find type == nText 
            {
                entityPM.InternalNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.InternalNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PrintNotes)) //T4 find type == nText 
            {
                entityPM.PrintNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PrintNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.TransferError)) //T4 find type == nText 
            {
                entityPM.TransferError = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.TransferError));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.AccountingExternalCode)) //T4 find type == nText 
            {
                entityPM.AccountingExternalCode = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.AccountingExternalCode));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.HouseNumber)) //T4 find type == nText 
            {
                entityPM.HouseNumber = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.HouseNumber));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.MasterNumber)) //T4 find type == nText 
            {
                entityPM.MasterNumber = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.MasterNumber));
