            if (!String.IsNullOrWhiteSpace(entityPM.SATAdditionalFieldsXML)) //T4 find type == nText 
            {
                entityPM.SATAdditionalFieldsXML = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SATAdditionalFieldsXML));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
